// MNB HR Identity Mapping for email
// Maps HR email attribute to identity warehouse email attribute

String hrEmail = (String)link.getAttribute("email");

if (hrEmail != null && !hrEmail.isEmpty()) {
    // Validate email format (basic check)
    if (hrEmail.matches(".+@.+\\..+")) {
        return hrEmail;
    } else {
        log.warn("Invalid email format from HR for identity " + identity.getName() + ": " + hrEmail);
        return null;
    }
}

return null;
